#!/usr/bin/env bash
# Output QA verdict to the reel's public "Showreel ready: <name>" issue (scripts/qa/output-qa.py; owner, 12 Nov 2026): on a FAIL it comments
# "NOT READY" with the failing checks (no links, no post text: issues are public), so the app, the owner and the next session see it.
# A reel with no such issue (tech reels) gets an issue of its own: "Output QA NOT READY: <name>".
# Usage: bash scripts/qa/notify.sh <name> <fails.txt>   (needs GH_TOKEN and REPO; does nothing when fails.txt is empty)
set -uo pipefail
NAME=$1; FAILS=$2
[ -s "$FAILS" ] || { echo "Output QA: nothing to report for $NAME"; exit 0; }
{ printf '**NOT READY (Output QA on the final MP4):** %s\n\n' "$NAME"; cat "$FAILS"; printf '\nRun: %s/%s/actions/runs/%s\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_\n' "${GITHUB_SERVER_URL:-https://github.com}" "$REPO" "${GITHUB_RUN_ID:-}"; } > oqa-body.md
N=$(gh api "repos/$REPO/issues?state=all&per_page=60" --jq ".[] | select(.title == \"Showreel ready: $NAME\") | .number" | head -1)
if [ -n "$N" ]; then gh api "repos/$REPO/issues/$N/comments" -F body=@oqa-body.md --jq .html_url && echo "NOT READY posted on issue #$N"
else gh issue create --repo "$REPO" --title "Output QA NOT READY: $NAME" --body-file oqa-body.md && echo "NOT READY issue opened for $NAME"; fi
